// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadOswald = makeLoadFont('Oswald');

// Load Oswald Google Font at module-level
const { fontFamily: oswaldFamily } = loadOswald();



export type AlcoholInfectionProps = Record<string, any>;

const AlcoholInfection: React.FC<AlcoholInfectionProps> = ({
  backgroundColor = "#f2f2f4",
  transparentBackground = false,
  durationInSeconds = 12,
  ballSizeRatio = 0.09,
  primaryColor = "#e6e6e8", // Sophisticated soft grey-white
  accentColor = "#e61c1c", // High-impact red
  labelText = "ALCOHOL",
  titleText = "SYSTEM CONTAMINATION",
  subtitleText = "The Cascade Effect of Alcohol Exposure",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const totalFrames = durationInSeconds * fps;
  const centerX = width / 2;
  const centerY = height / 2;
  const baseUnit = Math.min(width, height) * ballSizeRatio;
  const ballSize = baseUnit;

  // Keyframe Timing definitions (normalized relative to video duration)
  const tIntroStart = 0;
  
  const tCenterRedStart = totalFrames * 0.20;
  const tCenterRedEnd = totalFrames * 0.32;

  const tInfectStart = totalFrames * 0.35;
  const tInfectEnd = totalFrames * 0.55;

  const tRemoveCenterStart = totalFrames * 0.62;
  const tRemoveCenterEnd = totalFrames * 0.72;

  const tRecoverStart = totalFrames * 0.74;
  const tRecoverEnd = totalFrames * 0.92;

  // Ball Arrangement (mimics the reference's clustered grid layout)
  const ballsData = [
    // Layer 0: Center
    { id: 0, layer: 0, angle: 0 },

    // Layer 1: Inner (5 balls)
    { id: 1, layer: 1, angle: 0 },
    { id: 2, layer: 1, angle: 72 },
    { id: 3, layer: 1, angle: 144 },
    { id: 4, layer: 1, angle: 216 },
    { id: 5, layer: 1, angle: 288 },

    // Layer 2: Outer (10 balls offset to interleave with Inner ring)
    { id: 6, layer: 2, angle: 18 },
    { id: 7, layer: 2, angle: 54 },
    { id: 8, layer: 2, angle: 90 },
    { id: 9, layer: 2, angle: 126 },
    { id: 10, layer: 2, angle: 162 },
    { id: 11, layer: 2, angle: 198 },
    { id: 12, layer: 2, angle: 234 },
    { id: 13, layer: 2, angle: 270 },
    { id: 14, layer: 2, angle: 306 },
    { id: 15, layer: 2, angle: 342 },
  ];

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      {/* Studio Lighting Vignette */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: "radial-gradient(circle, transparent 20%, rgba(0,0,0,0.02) 70%, rgba(0,0,0,0.06) 100%)",
          pointerEvents: "none",
        }}
      />

      {/* Minimalist Header */}
      <div
        style={{
          position: "absolute",
          top: height * 0.06,
          left: width * 0.06,
          display: "flex",
          flexDirection: "column",
          gap: "4px",
          zIndex: 10,
        }}
      >
        <div
          style={{
            fontFamily: oswaldFamily,
            fontSize: Math.min(width, height) * 0.035,
            fontWeight: "bold",
            letterSpacing: "3px",
            color: "#18181b",
            textTransform: "uppercase",
          }}
        >
          {titleText}
        </div>
        <div
          style={{
            fontFamily: oswaldFamily,
            fontSize: Math.min(width, height) * 0.016,
            fontWeight: "normal",
            letterSpacing: "1px",
            color: "#71717a",
            textTransform: "uppercase",
          }}
        >
          {subtitleText}
        </div>
      </div>

      {/* Sphere Cluster Composition */}
      {ballsData.map((b) => {
        // Deterministic organic offset to mimic the beautiful manual alignment of the source
        const angleOffset = (random(`ball-angle-${b.id}`) - 0.5) * 6;
        const finalAngle = b.angle + angleOffset;
        const radiusOffset = (random(`ball-radius-${b.id}`) - 0.5) * (baseUnit * 0.06);

        const r = b.layer === 0
          ? 0
          : b.layer === 1
          ? baseUnit * 1.08 + radiusOffset
          : baseUnit * 2.12 + radiusOffset;

        const x = centerX + Math.cos(finalAngle * Math.PI / 180) * r;
        const y = centerY + Math.sin(finalAngle * Math.PI / 180) * r;

        // 1. Initial Scale-up Transition (bouncy stagger)
        const entryDelay = (b.layer === 0 ? 0 : b.layer === 1 ? 5 : 10) + (b.id % 4) * 2;
        const entrySpring = spring({
          frame: frame - entryDelay,
          fps,
          config: { damping: 13, mass: 0.9, stiffness: 110 },
        });
        const entryScale = interpolate(entrySpring, [0, 1], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });

        let scale = entryScale;
        let opacity = entryScale;
        let redness = 0;
        let isCenter = b.layer === 0;
        let textOpacity = 0;

        if (isCenter) {
          // Center Ball Color transition to Red (Phase 2)
          redness = interpolate(
            frame,
            [tCenterRedStart, tCenterRedEnd],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          // Center text "ALCOHOL" fades in smoothly
          textOpacity = interpolate(
            frame,
            [tCenterRedStart + 8, tCenterRedEnd],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          // Center Ball Removal (Phase 4)
          const removalScale = interpolate(
            frame,
            [tRemoveCenterStart, tRemoveCenterEnd],
            [1, 0],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );
          scale = entryScale * removalScale;
          opacity = entryScale * removalScale;
        } else {
          // Surrounding Balls: Infection Propagation Wave (Phase 3)
          const infectDuration = totalFrames * 0.05;
          const infectDelay = (b.layer === 1 ? 0 : totalFrames * 0.04) + ((b.angle || 0) / 360) * (totalFrames * 0.03);
          const infectStart = tInfectStart + infectDelay;
          const infectEnd = infectStart + infectDuration;

          const infectedProgress = interpolate(
            frame,
            [infectStart, infectEnd],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          // Surrounding Balls: Recovery Wave back to White (Phase 5)
          const recoverDuration = totalFrames * 0.05;
          const recoverDelay = (b.layer === 1 ? 0 : totalFrames * 0.04) + ((b.angle || 0) / 360) * (totalFrames * 0.03);
          const recoverStart = tRecoverStart + recoverDelay;
          const recoverEnd = recoverStart + recoverDuration;

          const recoveryProgress = interpolate(
            frame,
            [recoverStart, recoverEnd],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          // Calculate final color blend factor (0 = White, 1 = Infected Red)
          redness = infectedProgress * (1 - recoveryProgress);
        }

        // Custom High-Quality Shaded Gradients
        const whiteGrad = `radial-gradient(circle at 35% 25%, #ffffff 0%, ${primaryColor} 35%, #b4b4b8 75%, #88888c 100%)`;
        const redGrad = `radial-gradient(circle at 35% 25%, #ff8c8c 0%, ${accentColor} 40%, #ac1010 75%, #5a0202 100%)`;

        return (
          <React.Fragment key={b.id}>
            {/* Realistically Cast Shadow Beneath Sphere */}
            {opacity > 0 && (
              <div
                style={{
                  position: "absolute",
                  width: ballSize,
                  height: ballSize * 0.28,
                  backgroundColor: "rgba(0, 0, 0, 0.16)",
                  borderRadius: "50%",
                  filter: "blur(12px)",
                  transform: `translate(-50%, -50%) scale(${scale})`,
                  left: x,
                  top: y + ballSize * 0.46,
                  opacity: opacity * 0.95,
                  zIndex: 1,
                  pointerEvents: "none",
                  transition: "none",
                }}
              />
            )}

            {/* Main Physical Ball */}
            {opacity > 0 && (
              <div
                style={{
                  position: "absolute",
                  width: ballSize,
                  height: ballSize,
                  borderRadius: "50%",
                  transform: `translate(-50%, -50%) scale(${scale})`,
                  left: x,
                  top: y,
                  opacity: opacity,
                  zIndex: 2,
                  overflow: "hidden",
                  boxShadow: "inset -8px -8px 20px rgba(0,0,0,0.18), inset 8px 8px 18px rgba(255,255,255,0.45)",
                  transition: "none",
                }}
              >
                {/* Underlay White Shading */}
                <div
                  style={{
                    position: "absolute",
                    top: 0,
                    left: 0,
                    right: 0,
                    bottom: 0,
                    background: whiteGrad,
                    transition: "none",
                  }}
                />

                {/* Smooth Color Interpolation Layer (Avoids dynamic gradient string re-evaluation stutter) */}
                <div
                  style={{
                    position: "absolute",
                    top: 0,
                    left: 0,
                    right: 0,
                    bottom: 0,
                    background: redGrad,
                    opacity: redness,
                    transition: "none",
                  }}
                />

                {/* Central Dynamic Text */}
                {isCenter && (
                  <div
                    style={{
                      position: "absolute",
                      top: 0,
                      left: 0,
                      right: 0,
                      bottom: 0,
                      display: "flex",
                      justifyContent: "center",
                      alignItems: "center",
                      color: "#ffffff",
                      fontFamily: oswaldFamily,
                      fontSize: ballSize * 0.17,
                      fontWeight: "bold",
                      letterSpacing: "1.2px",
                      opacity: textOpacity,
                      textShadow: "0px 1px 4px rgba(0, 0, 0, 0.35)",
                      transition: "none",
                    }}
                  >
                    {labelText}
                  </div>
                )}
              </div>
            )}
          </React.Fragment>
        );
      })}
    </AbsoluteFill>
  );
};

export default AlcoholInfection;